parameters.jsCode:
// ============================================================
// RAYAH — FIND DUE AUTOMATIONS  (deterministic, UTC-correct)
// ============================================================
// Root-cause fixes:
//  1. Timezone-aware parsing of next_run. A naive timestamp (no Z / no
//     offset) is interpreted in the automation's timezone
//     (default Indian/Antananarivo, UTC+3) and converted to UTC — it is
//     NEVER blindly treated as UTC. This is what previously made every job
//     look "not due" for 3 hours.
//  2. Handles Date objects, luxon DateTime, ISO-Z, ISO+offset, and
//     space-separated SQL datetimes without producing "Invalid Date".
//  3. Recovers rows stuck in 'running' after a crashed execution.
//  4. Always emits either DUE items or ONE explicit NO_DUE control item so
//     the "Any Due?" gate is deterministic.

const STALE_MINUTES = 10;
const now    = Date.now();
const nowIso = new Date(now).toISOString();
const input  = $input.all();

// luxon is exposed as the global `DateTime` inside n8n Code nodes.
const LX = (typeof DateTime !== 'undefined') ? DateTime : null;

// Convert any stored next_run representation into an absolute UTC epoch (ms).
function toUtcMs(raw, tz) {
  if (raw === null || raw === undefined) return NaN;

  // Native Date object coming straight from the Data Table.
  if (raw instanceof Date) return raw.getTime();

  // luxon DateTime object.
  if (typeof raw === 'object' && typeof raw.toMillis === 'function') {
    return raw.toMillis();
  }

  let s = String(raw).trim();
  if (!s) return NaN;

  // Normalise "YYYY-MM-DD HH:MM:SS" (SQL style) to ISO.
  if (/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}/.test(s)) s = s.replace(' ', 'T');

  const hasZone = /[zZ]$/.test(s) || /[+-]\d{2}:?\d{2}$/.test(s);

  // Absolute timestamp — trust it as-is.
  if (hasZone) {
    const d = new Date(s);
    return d.getTime();
  }

  // Naive timestamp — interpret in the AUTOMATION timezone, not the server's.
  if (LX) {
    const dt = LX.fromISO(s, { zone: tz });
    if (dt.isValid) return dt.toMillis();
  }

  // Fallback when luxon / the zone is unavailable.
  // Antananarivo (EAT) is a fixed UTC+3 with no DST.
  const d = new Date(s + 'Z'); // read the wall-clock fields as if UTC
  if (Number.isNaN(d.getTime())) return NaN;
  const offsetMinutes = (tz === 'Indian/Antananarivo') ? 180 : 0;
  return d.getTime() - offsetMinutes * 60000;
}

const due = [];

for (const item of input) {
  const a = item.json ?? {};

  const id = Number(a.id ?? a.automation_id);
  if (!Number.isFinite(id)) continue;

  const status = String(a.status ?? '').trim().toLowerCase();
  const tz     = String(a.timezone ?? '').trim() || 'Indian/Antananarivo';

  const nextRunMs = toUtcMs(a.next_run, tz);

  let isDue     = false;
  let claimFrom = '';

  if (status === 'active') {
    // Normal path: active and its scheduled UTC time has arrived.
    if (Number.isFinite(nextRunMs) && nextRunMs <= now) {
      isDue = true;
      claimFrom = 'active';
    }
  } else if (status === 'running') {
    // Recovery path: a previous execution claimed this row but never
    // finished (crash / restart). Reclaim it once it is clearly stale.
    const claimMs = toUtcMs(a.claimed_at ?? a.last_run, tz);
    if (!Number.isFinite(claimMs) || (now - claimMs) > STALE_MINUTES * 60000) {
      isDue = true;
      claimFrom = 'running';
    }
  }

  if (!isDue) continue;

  due.push({
    ...a,

    id,
    automation_id: id,

    execution_mode: 'AUTOMATION',
    due: true,

    // Everything below is canonical UTC so the rest of the runner never has
    // to guess a timezone again (this self-heals the stored value on write).
    claim_from_status: claimFrom,
    claim_time: nowIso,
    due_at: Number.isFinite(nextRunMs) ? new Date(nextRunMs).toISOString() : nowIso,
    runner_now: nowIso,
    timezone: tz,
    next_run: Number.isFinite(nextRunMs)
      ? new Date(nextRunMs).toISOString()
      : String(a.next_run ?? '')
  });
}

// No due jobs -> one explicit control item -> Any Due? = FALSE -> Runner Idle.
if (due.length === 0) {
  return [{
    json: {
      _control: 'NO_DUE_AUTOMATIONS',
      due: false,
      checked_at: nowIso,
      checked_count: input.length
    }
  }];
}

return due;

return [{
  json: {
    ok: true,
    runner_status: 'idle',
    due: false,
    message: 'Runner checked successfully. No automation is due.',
    checked_at: new Date().toISOString()
  }
}];

// ============================================================
// RAYAH — PREPARE CLAIMED AUTOMATION
// ============================================================
// Re-hydrate the FULL automation payload from the in-memory Find Due
// snapshot (chat_space, message, recipient, subject, etc. all survive here),
// keyed by id. If the claim matched nothing (already claimed by a concurrent
// run) this node simply receives no input and does not execute — which is the
// intended de-duplication.

const dueRows = $('RAYAH — Find Due Automations1').all().map(i => i.json);
const id = Number($json.id ?? $json.automation_id);

const original = dueRows.find(a => Number(a.id ?? a.automation_id) === id);

if (!original) {
  throw new Error('Claimed automation ' + id + ' could not be restored from Find Due snapshot.');
}

return [{
  json: {
    ...original,
    id,
    automation_id: id,
    status: 'running',
    claim_acquired: true,
    claimed_at: new Date().toISOString()
  }
}];

