={{
(() => {
  const raw = String($json.chat_space ?? $json.space ?? '').trim();
  const space = raw
    .replace(/^https:\/\/chat\.googleapis\.com\/v1\//i, '')
    .replace(/^\/+/, '')
    .replace(/^(spaces\/)+/, 'spaces/');
  if (!/^spaces\/[^/]+$/.test(space)) {
    throw new Error('Invalid Google Chat chat_space: ' + raw);
  }
  return 'https://chat.googleapis.com/v1/' + space + '/messages';
})()
}}

