// ============================================================
// RAYAH — VERIFY GOOGLE CHAT
// ============================================================
// Success is based on the ACTUAL Google Chat API response, never on the mere
// fact that the HTTP node ran. With fullResponse enabled we have statusCode
// and body; a real success body contains name = "spaces/<space>/messages/<id>".

const original = $('RAYAH — Prepare Claimed Automation1').first().json;
const res      = $json ?? {};

const body = res.body ?? res;

const statusCode = Number(
  res.statusCode ??
  res.status ??
  body.statusCode ??
  0
);

const resource = String(
  body.name ??
  body.message?.name ??
  ''
).trim();

const success =
  (statusCode >= 200 && statusCode < 300) ||
  resource.startsWith('spaces/');

return [{
  json: {
    ...original,
    execution_result: 'google_chat',
    execution_success: success,
    http_status: statusCode || null,
    chat_message_resource: resource || null,
    provider_response: body
  }
}];

// ============================================================
// RAYAH — VERIFY GMAIL
// ============================================================
const original = $('RAYAH — Prepare Claimed Automation1').first().json;
const response = $json ?? {};

const messageId = String(response.id ?? response.messageId ?? '').trim();
const threadId  = String(response.threadId ?? '').trim();

const success = Boolean(messageId || threadId);

return [{
  json: {
    ...original,
    execution_result: 'gmail',
    execution_success: success,
    gmail_message_id: messageId || null,
    gmail_thread_id: threadId || null,
    provider_response: response
  }
}];

// ============================================================
// RAYAH — VERIFY RAYAH RESULT
// ============================================================
const original    = $('RAYAH — Prepare Claimed Automation1').first().json;
const response    = $json ?? {};
const serialized  = JSON.stringify(response).toLowerCase();

const explicitFailure =
  response.success === false ||
  response.ok === false ||
  Boolean(response.error) ||
  serialized.includes('"success":false') ||
  serialized.includes('"ok":false');

return [{
  json: {
    ...original,
    execution_result: 'rayah',
    execution_success: !explicitFailure,
    rayah_response: response
  }
}];

// ============================================================
// RAYAH — PREPARE FINAL AUTOMATION STATUS
// ============================================================
// Marks COMPLETED / ACTIVE strictly from verified provider execution.
// once  + success  -> completed (next_run kept unchanged, status excludes it)
// recur + success  -> active, next_run advanced in UTC
// any   + failure  -> active, retry in 5 minutes (run_count still increments)

const a   = $json ?? {};
const now = new Date();

const success      = a.execution_success === true;
const scheduleType = String(a.schedule_type ?? '').trim().toLowerCase();

const previous = new Date(String(a.next_run ?? ''));

function calculateNextRun() {
  if (Number.isNaN(previous.getTime())) return '';
  const d = new Date(previous);

  if (scheduleType === 'daily')  { d.setUTCDate(d.getUTCDate() + 1); return d.toISOString(); }
  if (scheduleType === 'weekly') { d.setUTCDate(d.getUTCDate() + 7); return d.toISOString(); }
  if (scheduleType === 'hourly') { d.setUTCHours(d.getUTCHours() + 1); return d.toISOString(); }

  if (scheduleType === 'monthly') {
    const originalDay = d.getUTCDate();
    d.setUTCDate(1);
    d.setUTCMonth(d.getUTCMonth() + 1);
    const lastDay = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth() + 1, 0)).getUTCDate();
    d.setUTCDate(Math.min(originalDay, lastDay));
    return d.toISOString();
  }
  return '';
}

let finalStatus, finalLastStatus, finalNextRun;

if (success) {
  finalLastStatus = 'success';
  if (scheduleType === 'once' || scheduleType === '') {
    finalStatus  = 'completed';
    // Keep the (past) next_run value; status='completed' excludes it from
    // Find Due, and we avoid writing '' into a dateTime column.
    finalNextRun = String(a.next_run ?? '');
  } else {
    finalStatus  = 'active';
    const nr = calculateNextRun();
    finalNextRun = nr || String(a.next_run ?? '');
  }
} else {
  // Failed jobs stay active and retry in 5 minutes.
  finalStatus     = 'active';
  finalLastStatus = 'failed';
  finalNextRun    = new Date(now.getTime() + 5 * 60 * 1000).toISOString();
}

return [{
  json: {
    ...a,
    final_status:      finalStatus,
    final_last_status: finalLastStatus,
    final_last_run:    now.toISOString(),
    final_next_run:    finalNextRun,
    final_run_count:   Number(a.run_count ?? 0) + 1
  }
}];

const a = $input.first()?.json ?? {};

return [{
  json: {
    ok: true,
    automation_id: a.id ?? null,
    name: a.name ?? '',
    status: a.final_status ?? '',
    last_status: a.final_last_status ?? '',
    execution_success: a.execution_success === true,
    execution_result: a.execution_result ?? '',
    http_status: a.http_status ?? null,
    chat_message_resource: a.chat_message_resource ?? null,
    next_run: a.final_next_run ?? '',
    last_run: a.final_last_run ?? '',
    run_count: a.final_run_count ?? 0,
    message: a.execution_success === true
      ? 'Automation executed successfully and provider execution was verified.'
      : 'Automation failed. It remains active and will retry in 5 minutes.'
  }
}];
